import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_unconverted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_occurrence_then_sorts_by_day_and_id():
    events = [
        {"id": "x", "day": 5},
        {"id": "b", "day": 2},
        {"id": "x", "day": 1},
        {"id": "a", "day": 2},
    ]
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_parser_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", "  \t", "  # comment", " a , 2 , 1 ", "b,3, 0", "c,4, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,extra", "a,two,1"])
def test_parser_error_uses_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" # skipped", "", bad_line])


def test_daily_counts_and_trailing_window():
    events = parse_session_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    counts = daily_conversion_counts(events, 2, 4)
    assert counts == [2, 0, 0]
    assert daily_conversion_counts(events, 4, 2) == []
    assert conversions_in_window(counts, 2) == 0
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 5) == 2


def test_campaign_uses_session_weighted_rate_and_calendar_days():
    groups = {
        "early": parse_session_log(["a,1,1"]),
        "late": parse_session_log(["b,5,0", "c,5,"]),
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 1 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"c": [{"converted": True}], "a": [{"converted": False}],
              "d": [], "b": [{"converted": True}]}
    assert top_converting_groups(groups, 1) == ["b"]
    assert top_converting_groups(groups, 5) == ["b", "c", "a"]
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", 0.0), ("b", 1.0), ("c", 1.0), ("d", None)
    ]


def test_streak_ends_at_nonpositive_counts():
    assert longest_conversion_streak([1, 0, 2, 1, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
